  `subcategory_id` int DEFAULT NULL,
  `tags_json` json DEFAULT NULL,
  `video_source` enum('upload','youtube','vimeo') DEFAULT 'upload',
  `video_url` varchar(500) DEFAULT NULL,
  `video_file_url` longtext,
  `duration_seconds` int DEFAULT '0',
  `difficulty_level_id` int DEFAULT NULL,
  `tutorial_type_id` int DEFAULT NULL,
  `key_takeaways` varchar(300) DEFAULT NULL,
  `thumbnail_url` longtext,
  `is_featured` tinyint(1) DEFAULT '0',
  `publish_date` date DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_company` (`company_id`),
  KEY `idx_category` (`category_id`),
  KEY `idx_subcategory` (`subcategory_id`),
  KEY `idx_difficulty` (`difficulty_level_id`),
  KEY `idx_type` (`tutorial_type_id`),
  KEY `idx_videos_company_order` (`company_id`,`is_active`,`sort_order`),
  CONSTRAINT `fk_vt_category` FOREIGN KEY (`category_id`) REFERENCES `company_website_video_tutorial_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_vt_difficulty` FOREIGN KEY (`difficulty_level_id`) REFERENCES `company_website_video_tutorial_difficulty_levels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_vt_subcategory` FOREIGN KEY (`subcategory_id`) REFERENCES `company_website_video_tutorial_subcategories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_vt_type` FOREIGN KEY (`tutorial_type_id`) REFERENCES `company_website_video_tutorial_types` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `company_websites`
