-- Table structure for `decorations`
CREATE TABLE IF NOT EXISTS `decorations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('corner','divider','ornament','top','bottom','motif') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'corner' COMMENT 'Placement, not design family',
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The uploaded PNG/JPG/WEBP/SVG — this IS the decoration',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Original filename, shown on the edit screen',
  `file_format` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PNG | SVG | JPG | WEBP, for the list Format column',
  `file_size` int unsigned DEFAULT NULL COMMENT 'Bytes as stored (post-compression), rendered as 245 KB',
  `is_active` tinyint NOT NULL DEFAULT '1',
