-- Table structure for `email_campaigns`
CREATE TABLE IF NOT EXISTS `email_campaigns` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_id` int DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `email_template_id` int NOT NULL,
  `email_config_id` int DEFAULT NULL,
  `campaign_type` enum('holiday','scheduled','recurring') COLLATE utf8mb4_unicode_ci NOT NULL,
  `holiday_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `holiday_month` int DEFAULT NULL,
  `holiday_day` int DEFAULT NULL,
  `scheduled_date` date DEFAULT NULL,
  `scheduled_time` time DEFAULT NULL,
  `recurring_pattern` enum('daily','weekly','monthly','yearly') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recurring_day` int DEFAULT NULL,
  `target_audience` enum('all_users','active_users','verified_users','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all_users',
  `target_roles` json DEFAULT NULL,
  `variable_mappings` json DEFAULT NULL,
  `total_recipients` int NOT NULL DEFAULT '0',
  `total_sent` int NOT NULL DEFAULT '0',
  `total_failed` int NOT NULL DEFAULT '0',
  `last_run_at` datetime DEFAULT NULL,
  `next_run_at` datetime DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending (draft)',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `email_configs`
CREATE TABLE IF NOT EXISTS `email_configs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driver` enum('smtp','brevo','elasticemail','sendmail') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'smtp',
  `host` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `port` int DEFAULT NULL,
  `username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `encryption` enum('tls','ssl','none') COLLATE utf8mb4_unicode_ci DEFAULT 'tls',
  `api_key` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `domain` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imap_host` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imap_port` int DEFAULT '993',
  `imap_encryption` enum('ssl','tls','none') COLLATE utf8mb4_unicode_ci DEFAULT 'ssl',
  `imap_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Enable IMAP polling for inbound replies',
  `company_id` int DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `email_queue`
CREATE TABLE IF NOT EXISTS `email_queue` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL,
  `campaign_id` int NOT NULL,
  `user_id` int NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','processing','sent','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `priority` int NOT NULL DEFAULT '5' COMMENT '1=highest,10=lowest',
  `attempts` int NOT NULL DEFAULT '0',
  `max_attempts` int NOT NULL DEFAULT '3',
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `scheduled_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `processed_at` datetime DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `email_config_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_queue_status_scheduled` (`status`,`scheduled_at`),
  KEY `idx_queue_campaign_user` (`campaign_id`,`user_id`),
  KEY `idx_queue_priority` (`priority`,`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `email_sent_logs`
CREATE TABLE IF NOT EXISTS `email_sent_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL,
  `campaign_id` int NOT NULL,
  `user_id` int NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `response` text COLLATE utf8mb4_unicode_ci,
  `email_config_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `email_templates`
CREATE TABLE IF NOT EXISTS `email_templates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_id` int DEFAULT NULL,
  `type` enum('header','footer','template') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'template',
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body` longtext COLLATE utf8mb4_unicode_ci,
  `variables` json DEFAULT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `header_id` int DEFAULT NULL,
  `footer_id` int DEFAULT NULL,
  `email_config_id` int DEFAULT NULL,
  `is_predefined` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_categories`
CREATE TABLE IF NOT EXISTS `event_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_categories_listing` (`company_id`,`deleted_at`,`is_active`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guest_groups`
CREATE TABLE IF NOT EXISTS `event_guest_groups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `company_id` int DEFAULT NULL,
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT '#EC4899',
  `visibility` enum('private','public') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'private',
  `is_default` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_guest_groups_client` (`website_client_id`,`deleted_at`),
  KEY `idx_guest_groups_default` (`website_client_id`,`is_default`,`deleted_at`),
  CONSTRAINT `fk_guest_groups_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guest_notes`
-- The host's own notes ABOUT a guest. `event_guests`.`notes` is a different
-- thing and STAYS: that is what the GUEST said with their response. Two
-- authors, two lifetimes — merging them loses which of the two a sentence
-- came from.
CREATE TABLE IF NOT EXISTS `event_guest_notes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `guest_id` int unsigned NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` mediumtext COLLATE utf8mb4_unicode_ci COMMENT 'HTML from the rich text editor',
  `category` enum('general','personal','dietary','communication','reminder','logistics') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `visibility` enum('internal','shared') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'internal' COMMENT 'shared is reserved: nothing shows a guest their notes yet',
  `is_pinned` tinyint NOT NULL DEFAULT '0',
  `created_by_client_id` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_guest_notes_guest` (`guest_id`,`deleted_at`),
  KEY `idx_guest_notes_client` (`website_client_id`,`deleted_at`),
  KEY `idx_guest_notes_pinned` (`guest_id`,`is_pinned`,`created_at`),
  CONSTRAINT `fk_guest_notes_guest` FOREIGN KEY (`guest_id`) REFERENCES `event_guests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_guest_notes_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guest_reminders`
-- `status` DOES NOT store "upcoming" or "overdue" — that is a fact about
-- `due_at` versus now, and a stored one goes stale the moment the date passes.
-- Nothing FIRES these: no job runner, no SMTP. It is a list the host reads.
CREATE TABLE IF NOT EXISTS `event_guest_reminders` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `guest_id` int unsigned NOT NULL,
  `note_id` int unsigned DEFAULT NULL COMMENT 'Optional: a reminder can stand on its own',
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `due_at` datetime NOT NULL,
  `status` enum('pending','done','dismissed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Upcoming / overdue is DERIVED from due_at, never stored',
  `completed_at` datetime DEFAULT NULL,
  `created_by_client_id` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_guest_reminders_guest` (`guest_id`,`deleted_at`),
  KEY `idx_guest_reminders_due` (`website_client_id`,`status`,`due_at`),
  KEY `idx_guest_reminders_note` (`note_id`),
  CONSTRAINT `fk_guest_reminders_guest` FOREIGN KEY (`guest_id`) REFERENCES `event_guests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_guest_reminders_note` FOREIGN KEY (`note_id`) REFERENCES `event_guest_notes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_guest_reminders_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guest_response_logs`
-- APPEND ONLY. Nothing updates or deletes a row here — a history you can edit
-- is not a history. The CURRENT answer still lives on `event_guests`; this is
-- how it got there, and the two are never alternatives to each other.
-- `from_response_type` is NULL on a first entry: there was no previous answer,
-- and 'none' would claim they had actively said nothing before.
CREATE TABLE IF NOT EXISTS `event_guest_response_logs` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `guest_id` int unsigned NOT NULL,
  `event_id` int unsigned NOT NULL COMMENT 'Denormalised on purpose: the tab lists one person across many events',
  `from_response_type` enum('none','yes','no','maybe') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = the first entry. Not the same as none',
  `to_response_type` enum('none','yes','no','maybe') COLLATE utf8mb4_unicode_ci NOT NULL,
  `party_size` tinyint unsigned NOT NULL DEFAULT '1',
  `dietary_preference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `accommodation` enum('unknown','required','not_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'What the guest said with THIS answer',
  `source` enum('client','guest','import','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'client' COMMENT 'client = the host edited it. guest = they answered themselves',
  `changed_by_client_id` int unsigned DEFAULT NULL,
  `changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_response_logs_guest` (`guest_id`,`changed_at`),
  KEY `idx_response_logs_client` (`website_client_id`,`changed_at`),
  KEY `idx_response_logs_event` (`event_id`),
  CONSTRAINT `fk_response_logs_guest` FOREIGN KEY (`guest_id`) REFERENCES `event_guests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_response_logs_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_response_logs_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guest_tags`
-- A row per tag, not a JSON array on the guest: tags are the thing people
-- filter and count by, and a JSON column cannot be indexed for that.
-- The UNIQUE key includes `deleted_at` so removing a tag does not hold its
-- label hostage against being added back.
CREATE TABLE IF NOT EXISTS `event_guest_tags` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `guest_id` int unsigned NOT NULL,
  `label` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = let the UI derive it from the label, so no two screens disagree',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_guest_tag` (`guest_id`,`label`,`deleted_at`),
  KEY `idx_guest_tags_client` (`website_client_id`,`deleted_at`),
  KEY `idx_guest_tags_label` (`website_client_id`,`label`,`deleted_at`),
  CONSTRAINT `fk_guest_tags_guest` FOREIGN KEY (`guest_id`) REFERENCES `event_guests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_guest_tags_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_guests`
CREATE TABLE IF NOT EXISTS `event_guests` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `event_id` int unsigned NOT NULL,
  `website_client_id` int unsigned NOT NULL,
  `company_id` int DEFAULT NULL,
  `group_id` int unsigned DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mr. / Ms. / Mrs.',
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dial_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT '+91',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `whatsapp` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Often differs from mobile',
  `company` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `table_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Merge field {table_number}',
  `party_size` tinyint unsigned NOT NULL DEFAULT '1',
  `rsvp_status` enum('not_responded','invited','pending','accepted','declined') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'not_responded',
  `invite_source` enum('whatsapp','email','sms','manual','import') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `invited_at` datetime DEFAULT NULL COMMENT 'NULL = added but not yet invited',
  `responded_at` datetime DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `address_line1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_line2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `postal_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'India',
  `dietary_preference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `special_requirements` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plus_one` tinyint NOT NULL DEFAULT '0',
  `plus_one_count` tinyint unsigned NOT NULL DEFAULT '0',
  `custom_answers` json DEFAULT NULL COMMENT 'Answers to per-event custom questions',
  `response_type` enum('none','yes','no','maybe') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none' COMMENT 'What the guest said. Separate from rsvp_status, which is where the invitation has got to',
  `photo` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Guest portrait, same storage as every other upload',
  `accommodation` enum('unknown','required','not_required') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown' COMMENT 'unknown = never asked, which is not the same as not_required',
  `relationship` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Relationship / Role on the profile header. Free text: a fixed list would exclude the real one',
  `added_by_client_id` int unsigned DEFAULT NULL COMMENT 'Who added this guest. NULL = added before this was recorded, and stays NULL',
  PRIMARY KEY (`id`),
  KEY `idx_event_guests_event` (`event_id`,`deleted_at`),
  KEY `idx_event_guests_client` (`website_client_id`,`deleted_at`),
  KEY `idx_event_guests_status` (`rsvp_status`,`deleted_at`),
  KEY `idx_event_guests_source` (`invite_source`,`deleted_at`),
  KEY `idx_event_guests_responded` (`responded_at`),
  KEY `idx_event_guests_group` (`group_id`,`deleted_at`),
  CONSTRAINT `fk_event_guests_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_event_guests_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_event_guests_group` FOREIGN KEY (`group_id`) REFERENCES `event_guest_groups` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_menus`
CREATE TABLE IF NOT EXISTS `event_menus` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `remarks` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'free-form internal note',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'what this menu is for — shown on the view page',
  `menu_group` enum('core','additional','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'core',
  `event_category_id` int unsigned DEFAULT NULL,
  `event_type_id` int unsigned DEFAULT NULL,
  `religion_id` int unsigned DEFAULT NULL,
  `is_website` tinyint NOT NULL DEFAULT '1' COMMENT 'menu type: website',
  `is_mobile` tinyint NOT NULL DEFAULT '1' COMMENT 'menu type: mobile app',
  `display_website` tinyint NOT NULL DEFAULT '1' COMMENT 'show/hide on website',
  `display_mobile` tinyint NOT NULL DEFAULT '1' COMMENT 'show/hide on mobile app',
  `active_website` tinyint NOT NULL DEFAULT '1' COMMENT 'active/inactive on website',
  `active_mobile` tinyint NOT NULL DEFAULT '1' COMMENT 'active/inactive on mobile app',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_menus_listing` (`company_id`,`deleted_at`,`sort_order`),
  KEY `idx_event_menus_category` (`company_id`,`event_category_id`,`deleted_at`),
  KEY `idx_event_menus_type` (`company_id`,`event_type_id`,`deleted_at`),
  KEY `idx_event_menus_religion` (`company_id`,`religion_id`,`deleted_at`),
  KEY `idx_event_menus_platform` (`company_id`,`is_website`,`is_mobile`,`deleted_at`),
  KEY `idx_event_menus_slug` (`company_id`,`slug`),
  KEY `fk_event_menus_category` (`event_category_id`),
  KEY `fk_event_menus_type` (`event_type_id`),
  KEY `fk_event_menus_religion` (`religion_id`),
  KEY `idx_event_menus_group` (`company_id`,`menu_group`,`deleted_at`),
  CONSTRAINT `fk_event_menus_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_menus_religion` FOREIGN KEY (`religion_id`) REFERENCES `religions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_menus_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_message_campaigns`
CREATE TABLE IF NOT EXISTS `event_message_campaigns` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL,
  `event_id` int unsigned NOT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` mediumtext COLLATE utf8mb4_unicode_ci,
  `channel` enum('email','sms','whatsapp','push') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'email',
  `kind` enum('invite','reminder','update','thank_you','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'invite',
  `audience` enum('all','groups','guests') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `group_ids` json DEFAULT NULL,
  `guest_ids` json DEFAULT NULL,
  `recipients_count` int unsigned NOT NULL DEFAULT '0',
  `status` enum('draft','scheduled','sending','sent','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `scheduled_at` datetime DEFAULT NULL,
  `window_start` time DEFAULT NULL,
  `window_end` time DEFAULT NULL,
  `timezone` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sent_at` datetime DEFAULT NULL,
  `failed_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_campaigns_client` (`website_client_id`,`deleted_at`),
  KEY `idx_campaigns_event` (`event_id`,`deleted_at`),
  KEY `idx_campaigns_status` (`status`,`deleted_at`),
  KEY `idx_campaigns_sent` (`sent_at`),
  CONSTRAINT `fk_campaigns_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_campaigns_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_messages`
CREATE TABLE IF NOT EXISTS `event_messages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `event_id` int unsigned NOT NULL,
  `campaign_id` int unsigned DEFAULT NULL,
  `guest_id` int unsigned DEFAULT NULL,
  `website_client_id` int unsigned NOT NULL,
  `channel` enum('whatsapp','email','sms') COLLATE utf8mb4_unicode_ci NOT NULL,
  `kind` enum('invite','reminder','update','thank_you') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'invite',
  `status` enum('queued','sent','delivered','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sent',
  `sent_at` datetime DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `opened_at` datetime DEFAULT NULL,
  `clicked_at` datetime DEFAULT NULL,
  `failed_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sender` enum('client','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT 'Who caused this message. One login per account, so this is the ACTOR, not a user',
  `sender_client_id` int unsigned DEFAULT NULL COMMENT 'The account that sent it, when sender = client',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_messages_event` (`event_id`,`deleted_at`),
  KEY `idx_event_messages_client` (`website_client_id`,`deleted_at`),
  KEY `idx_event_messages_channel` (`channel`,`deleted_at`),
  KEY `idx_event_messages_sent` (`sent_at`),
  KEY `fk_event_messages_guest` (`guest_id`),
  KEY `idx_event_messages_campaign` (`campaign_id`,`deleted_at`),
  CONSTRAINT `fk_event_messages_campaign` FOREIGN KEY (`campaign_id`) REFERENCES `event_message_campaigns` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_event_messages_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_event_messages_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_event_messages_guest` FOREIGN KEY (`guest_id`) REFERENCES `event_guests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_templates`
CREATE TABLE IF NOT EXISTS `event_templates` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL COMMENT 'Same scoping every other admin module uses',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Template code / slug, e.g. FWE-001. Unique per company, enforced in the service so a soft-deleted row cannot hold one hostage',
  `event_category_id` int unsigned DEFAULT NULL,
  `event_type_id` int unsigned DEFAULT NULL,
  `religion_id` int unsigned DEFAULT NULL COMMENT 'Optional - not every event is religious',
  `template_category_id` int unsigned DEFAULT NULL COMMENT 'Step 1 Style — replaces the hardcoded enum',
  `style` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'classic' COMMENT 'Template style/theme: classic|floral|royal|minimal|modern|traditional',
  `tags` json DEFAULT NULL COMMENT 'Free-text tags, for search only',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Visible to clients in the gallery',
  `layout_style` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'classic' COMMENT 'classic|modern|elegant|minimal|traditional',
  `background_type` enum('color','image','gradient','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'color',
  `background_color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hex, #RRGGBB or #RRGGBBAA',
  `secondary_color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `background_image` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gradient_from` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gradient_to` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gradient_via` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional third gradient stop. NULL = two-stop gradient',
  `image_position` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'center' COMMENT 'Nine-way placement for background_type = image',
  `image_scale` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cover' COMMENT 'cover|contain|fill|auto',
  `background_position` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'center' COMMENT 'Nine-way placement for background_type = custom',
  `image_size` int NOT NULL DEFAULT '100' COMMENT 'Percent scale of the custom design, 10-400',
  `overlay_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Whether the tint is drawn at all',
  `overlay_color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Overlay tint. NULL = the black the preview has always used',
  `artwork_style` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Traditional custom backgrounds only',
  `gradient_type` enum('linear','radial') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'linear',
  `gradient_direction` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'bottom' COMMENT 'top|top-right|right|bottom-right|bottom|bottom-left|left|top-left',
  `image_shape` enum('rectangle','square','circle','heart','arch') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'rectangle' COMMENT 'Custom background only',
  `corner_radius` int NOT NULL DEFAULT '0' COMMENT '0-100 percent, Custom background only',
  `overlay_opacity` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0-100, darkens the background so text stays readable',
  `orientation` enum('portrait','landscape') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'portrait',
  `dimension` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. 1080x1920',
  `primary_font` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secondary_font` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `border_style` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frame_style_id` int unsigned DEFAULT NULL COMMENT 'Step 2 Border / Frame Style — the real artwork',
  `decoration_ids` json DEFAULT NULL COMMENT 'Step 2 Decorations — ids into `decorations`',
  `components` json DEFAULT NULL COMMENT 'Map of component key -> 0|1. WHETHER it shows',
  `component_order` json DEFAULT NULL COMMENT 'Ordered array of component keys. WHERE it shows. Kept separate so toggling one off and on again does not send it to the bottom',
  `permissions` json DEFAULT NULL COMMENT 'Map of component/aspect key -> 0|1. What a client may edit after choosing this template',
  `status` enum('draft','published') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'Save as Draft vs Save & Publish. Independent of is_active',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT 'Active/Inactive on the list',
  `is_featured` tinyint NOT NULL DEFAULT '0',
  `available_for` json DEFAULT NULL COMMENT 'Subset of ["individual","company"]. Both is both entries, not a third value',
  `plan_availability` enum('all','selected','trial') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `plan_ids` json DEFAULT NULL COMMENT 'subscription_plans ids, plan_availability = selected only',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT 'Lower appears first',
  `show_on_homepage` tinyint NOT NULL DEFAULT '0',
  `thumbnail` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Gallery card image, 600x400',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_templates_company` (`company_id`,`deleted_at`),
  KEY `idx_event_templates_code` (`company_id`,`code`,`deleted_at`),
  KEY `idx_event_templates_category` (`event_category_id`,`deleted_at`),
  KEY `idx_event_templates_type` (`event_type_id`,`deleted_at`),
  KEY `idx_event_templates_religion` (`religion_id`,`deleted_at`),
  KEY `idx_event_templates_status` (`is_active`,`deleted_at`),
  KEY `idx_event_templates_featured` (`is_featured`,`deleted_at`),
  KEY `idx_event_templates_listing` (`company_id`,`sort_order`,`deleted_at`),
  KEY `idx_event_templates_tpl_category` (`template_category_id`),
  KEY `idx_event_templates_frame` (`frame_style_id`),
  CONSTRAINT `fk_event_templates_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_templates_frame` FOREIGN KEY (`frame_style_id`) REFERENCES `frame_styles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_templates_religion` FOREIGN KEY (`religion_id`) REFERENCES `religions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_templates_tpl_category` FOREIGN KEY (`template_category_id`) REFERENCES `template_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_event_templates_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=148 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `event_types`
CREATE TABLE IF NOT EXISTS `event_types` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `event_category_id` int unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_event_types_listing` (`company_id`,`deleted_at`,`is_active`,`sort_order`),
  KEY `idx_event_types_category` (`company_id`,`event_category_id`,`deleted_at`),
  KEY `fk_event_types_category` (`event_category_id`),
  CONSTRAINT `fk_event_types_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `events`
CREATE TABLE IF NOT EXISTS `events` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `website_client_id` int unsigned NOT NULL COMMENT 'Owner - the signed-in portal client',
  `vendor_id` int unsigned NOT NULL DEFAULT '1' COMMENT 'Tenant whose website the client belongs to',
  `company_id` int DEFAULT NULL COMMENT 'Same scoping every other admin module uses',
  `subscription_plan_id` int unsigned DEFAULT NULL,
  `event_category_id` int unsigned DEFAULT NULL,
  `event_type_id` int unsigned DEFAULT NULL,
  `religion_id` int unsigned DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tagline` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `timezone` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `venue_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Not collected by the wizard yet; the dashboard card renders it when present',
  `venue_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `privacy` enum('private','public','unlisted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'private',
  `status` enum('draft','upcoming','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'upcoming' COMMENT 'Past is derived from end_date at read time, never stored',
  `menu_ids` json DEFAULT NULL,
  `theme_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primary_color` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hex, #RRGGBB or #RRGGBBAA',
  `qr_token` text COLLATE utf8mb4_unicode_ci,
  `qr_version` tinyint unsigned NOT NULL DEFAULT '1',
  `qr_issued_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_events_client` (`website_client_id`,`deleted_at`),
  KEY `idx_events_company` (`company_id`,`deleted_at`),
  KEY `idx_events_vendor` (`vendor_id`,`deleted_at`),
  KEY `idx_events_status` (`status`,`deleted_at`),
  KEY `idx_events_start` (`start_date`),
  KEY `fk_events_plan` (`subscription_plan_id`),
  KEY `fk_events_category` (`event_category_id`),
  KEY `fk_events_type` (`event_type_id`),
  KEY `fk_events_religion` (`religion_id`),
  CONSTRAINT `fk_events_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_events_client` FOREIGN KEY (`website_client_id`) REFERENCES `website_clients` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_events_plan` FOREIGN KEY (`subscription_plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_events_religion` FOREIGN KEY (`religion_id`) REFERENCES `religions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_events_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `faq_categories`
CREATE TABLE IF NOT EXISTS `faq_categories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL DEFAULT '1',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_faq_cat_company` (`company_id`),
  KEY `idx_faq_cat_active` (`is_active`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `faqs`
CREATE TABLE IF NOT EXISTS `faqs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL DEFAULT '1',
  `faq_category_id` int NOT NULL,
  `question` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `answer` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_faqs_company` (`company_id`),
  KEY `idx_faqs_category` (`faq_category_id`),
  KEY `idx_faqs_active` (`is_active`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `frame_styles`
CREATE TABLE IF NOT EXISTS `frame_styles` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_category_id` int unsigned DEFAULT NULL,
  `file_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The uploaded SVG/PNG/JPG — this IS the frame',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Original filename, shown on the edit screen',
  `supported_layouts` json DEFAULT NULL COMMENT 'Subset of portrait|landscape|square',
  `status` enum('draft','published') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published' COMMENT 'Save as Draft vs Upload Style',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT 'The form Status toggle — separate from draft/published',
  `sort_order` int NOT NULL DEFAULT '0',
  `company_id` int DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_frame_styles_company` (`company_id`,`deleted_at`),
  KEY `idx_frame_styles_category` (`template_category_id`,`deleted_at`),
  KEY `idx_frame_styles_status` (`is_active`,`deleted_at`),
  KEY `idx_frame_styles_listing` (`company_id`,`sort_order`,`deleted_at`),
  CONSTRAINT `fk_frame_styles_category` FOREIGN KEY (`template_category_id`) REFERENCES `template_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `languages`
CREATE TABLE IF NOT EXISTS `languages` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `native_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direction` enum('ltr','rtl') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ltr',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `localities`
CREATE TABLE IF NOT EXISTS `localities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `city_id` int NOT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pincode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_localities_city` (`city_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `mail_folders`
CREATE TABLE IF NOT EXISTS `mail_folders` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `owner_type` enum('admin','vendor','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner_id` int unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mf_owner` (`owner_type`,`owner_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `mail_notifications`
CREATE TABLE IF NOT EXISTS `mail_notifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mail_id` bigint unsigned NOT NULL,
  `recipient_type` enum('admin','vendor','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipient_id` int unsigned NOT NULL,
  `is_read` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_mn_recipient` (`recipient_type`,`recipient_id`,`is_read`),
  KEY `fk_mn_mail` (`mail_id`),
  CONSTRAINT `fk_mn_mail` FOREIGN KEY (`mail_id`) REFERENCES `mails` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `mail_recipients`
CREATE TABLE IF NOT EXISTS `mail_recipients` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mail_id` bigint unsigned NOT NULL,
  `recipient_type` enum('admin','vendor','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipient_id` int unsigned NOT NULL,
  `role` enum('to','cc','bcc') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'to',
  `is_read` tinyint NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1',
  `label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `custom_folder_id` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_mr_mail` (`mail_id`),
  KEY `idx_mr_recipient` (`recipient_type`,`recipient_id`),
  KEY `idx_mr_folder` (`custom_folder_id`),
  CONSTRAINT `fk_mr_folder` FOREIGN KEY (`custom_folder_id`) REFERENCES `mail_folders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_mr_mail` FOREIGN KEY (`mail_id`) REFERENCES `mails` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `mails`
CREATE TABLE IF NOT EXISTS `mails` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int unsigned DEFAULT NULL,
  `sender_type` enum('admin','vendor','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sender_id` int unsigned NOT NULL,
  `subject` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('draft','sent','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `sent_at` datetime DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `sender_is_active` tinyint NOT NULL DEFAULT '1',
  `sender_label` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sender_custom_folder_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mails_sender` (`sender_type`,`sender_id`),
  KEY `idx_mails_status` (`status`),
  KEY `idx_mails_sender_state` (`sender_type`,`sender_id`,`sender_is_active`),
  KEY `idx_mails_sender_folder` (`sender_type`,`sender_id`,`sender_custom_folder_id`),
  KEY `idx_sender_id` (`sender_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `menus`
CREATE TABLE IF NOT EXISTS `menus` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `icon_fill_color_light` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `icon_fill_color_dark` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active',
  `display_status` tinyint NOT NULL DEFAULT '1' COMMENT '0=hidden, 1=visible',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_menus_company_id` (`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `missing_translation_keys`
CREATE TABLE IF NOT EXISTS `missing_translation_keys` (
  `id` int NOT NULL AUTO_INCREMENT,
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_id` int DEFAULT NULL,
  `default_value` text COLLATE utf8mb4_unicode_ci,
  `page_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `report_count` int NOT NULL DEFAULT '1',
  `first_reported_at` datetime DEFAULT NULL,
  `last_reported_at` datetime DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=resolved/ignored,1=pending,2=in-progress',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `key` (`key`),
  KEY `idx_missing_key` (`key`),
  KEY `idx_missing_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=170 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `modules`
CREATE TABLE IF NOT EXISTS `modules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `company_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `payments`
CREATE TABLE IF NOT EXISTS `payments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `status` enum('pending','completed','failed','refunded','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `gateway` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'stripe, paypal, razorpay, etc.',
  `gateway_transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `metadata` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payments_company` (`company_id`),
  KEY `idx_payments_user` (`user_id`),
  KEY `idx_payments_status` (`status`),
  KEY `idx_payments_gateway` (`gateway`),
  KEY `idx_payments_txn` (`gateway_transaction_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `permissions`
CREATE TABLE IF NOT EXISTS `permissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `module_id` int DEFAULT NULL,
  `module` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_permissions_slug` (`slug`),
  KEY `idx_permissions_module` (`module`),
  KEY `fk_permissions_module` (`module_id`),
  CONSTRAINT `fk_permissions_module` FOREIGN KEY (`module_id`) REFERENCES `modules` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=387 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `pincodes`
CREATE TABLE IF NOT EXISTS `pincodes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `city_id` int NOT NULL,
  `pincode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `area_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pincodes_city` (`city_id`),
  KEY `idx_pincodes_code` (`pincode`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `plan_badge_plans`
CREATE TABLE IF NOT EXISTS `plan_badge_plans` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `badge_id` int unsigned NOT NULL,
  `plan_id` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_badge_plan` (`badge_id`,`plan_id`),
  KEY `idx_badge_plans_plan` (`plan_id`),
  CONSTRAINT `fk_badge_plans_badge` FOREIGN KEY (`badge_id`) REFERENCES `plan_badges` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_badge_plans_plan` FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `plan_badges`
CREATE TABLE IF NOT EXISTS `plan_badges` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `text` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'kept short — it renders on a plan card',
  `style` enum('default','rounded','pill','outline','soft','dashed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#6E22FE',
  `apply_to` enum('all','selected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `sort_order` int NOT NULL DEFAULT '0',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_plan_badges_listing` (`company_id`,`deleted_at`,`is_active`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `plan_types`
CREATE TABLE IF NOT EXISTS `plan_types` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `menu_ids` json DEFAULT NULL COMMENT 'Array of menu IDs',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `validity` int DEFAULT NULL COMMENT 'Days, NULL = no expiry',
  `features` longtext COLLATE utf8mb4_unicode_ci COMMENT 'Rich HTML content',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active',
  `is_custom` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=custom plan for specific vendor',
  `vendor_id` int unsigned DEFAULT NULL COMMENT 'FK to vendors.id (only when is_custom=1)',
  `discounted_price` decimal(10,2) DEFAULT NULL COMMENT 'Price after discount',
  `label_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_subscriptions_company_id` (`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `plugins`
CREATE TABLE IF NOT EXISTS `plugins` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '0' COMMENT '0=disabled,1=enabled',
  `config_group` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `config_route` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plugin_slug_company` (`slug`,`company_id`),
  KEY `idx_plugins_company` (`company_id`),
  KEY `idx_plugins_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `refresh_tokens`
CREATE TABLE IF NOT EXISTS `refresh_tokens` (
  `id` int NOT NULL AUTO_INCREMENT,
  `token` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` int NOT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `expires_at` datetime NOT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `token` (`token`),
  KEY `idx_refresh_tokens_user` (`user_id`),
  CONSTRAINT `fk_refresh_tokens_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `religions`
CREATE TABLE IF NOT EXISTS `religions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `event_type_id` int unsigned NOT NULL,
  `event_category_id` int unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_religions_listing` (`company_id`,`deleted_at`,`is_active`,`sort_order`),
  KEY `idx_religions_scope` (`company_id`,`event_category_id`,`event_type_id`,`deleted_at`),
  KEY `fk_religions_category` (`event_category_id`),
  KEY `fk_religions_type` (`event_type_id`),
  CONSTRAINT `fk_religions_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_religions_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `role_permissions`
CREATE TABLE IF NOT EXISTS `role_permissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `role_id` int NOT NULL,
  `permission_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `requires_approval` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_permission` (`role_id`,`permission_id`),
  KEY `fk_rp_permission` (`permission_id`),
  CONSTRAINT `fk_rp_permission` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rp_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1539 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `roles`
CREATE TABLE IF NOT EXISTS `roles` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `level` int NOT NULL DEFAULT '0' COMMENT 'developer=1000,super_admin=100,admin=50,subadmin=25,custom=10',
  `company_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `approved_at` datetime DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_roles_company` (`company_id`),
  KEY `idx_roles_slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `sequelizemeta`
CREATE TABLE IF NOT EXISTS `sequelizemeta` (
  `name` varchar(255) COLLATE utf8mb3_unicode_ci NOT NULL,
  PRIMARY KEY (`name`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

-- Table structure for `settings`
CREATE TABLE IF NOT EXISTS `settings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci,
  `group` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `type` enum('text','textarea','number','boolean','json','file') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text',
  `description` text COLLATE utf8mb4_unicode_ci,
  `company_id` int DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `key` (`key`),
  KEY `idx_settings_group` (`group`)
) ENGINE=InnoDB AUTO_INCREMENT=222 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `states`
CREATE TABLE IF NOT EXISTS `states` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country_id` int NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_states_country` (`country_id`),
  CONSTRAINT `fk_states_country` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4958 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `subscription_plan_menus`
CREATE TABLE IF NOT EXISTS `subscription_plan_menus` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `plan_id` int unsigned NOT NULL,
  `menu_id` int unsigned NOT NULL,
  `for_website` tinyint NOT NULL DEFAULT '0',
  `for_mobile` tinyint NOT NULL DEFAULT '0',
  `limits_json` json DEFAULT NULL COMMENT 'screen 4 limits, keyed by the menu limit catalogue',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_plan_menu` (`plan_id`,`menu_id`),
  KEY `idx_plan_menus_menu` (`menu_id`),
  CONSTRAINT `fk_plan_menus_menu` FOREIGN KEY (`menu_id`) REFERENCES `event_menus` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_plan_menus_plan` FOREIGN KEY (`plan_id`) REFERENCES `subscription_plans` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `subscription_plans`
CREATE TABLE IF NOT EXISTS `subscription_plans` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plan_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'internal reference, no spaces',
  `plan_type_id` int DEFAULT NULL,
  `billing_cycle` enum('monthly','quarterly','yearly','lifetime') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'monthly',
  `short_description` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `for_website` tinyint NOT NULL DEFAULT '1',
  `for_mobile` tinyint NOT NULL DEFAULT '1',
  `event_category_id` int unsigned DEFAULT NULL,
  `event_type_id` int unsigned DEFAULT NULL,
  `religion_id` int unsigned DEFAULT NULL,
  `currency_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `trial_days` int NOT NULL DEFAULT '0' COMMENT '0 = no trial',
  `is_visible` tinyint NOT NULL DEFAULT '1' COMMENT 'Plan Visibility on the view screen',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive, 1=active, 2=pending approval',
  `sort_order` int NOT NULL DEFAULT '0',
  `plan_badge_id` int unsigned DEFAULT NULL COMMENT 'badge shown on this plan card; NULL = none',
  `company_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `deactivation_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'from the reason dropdown',
  `deactivation_comments` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'matches the 0/300 counter',
  `deactivated_at` datetime DEFAULT NULL,
  `deactivated_by` int unsigned DEFAULT NULL,
  `deletion_reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deletion_comments` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_subscription_plans_listing` (`company_id`,`deleted_at`,`sort_order`),
  KEY `idx_subscription_plans_code` (`company_id`,`plan_code`),
  KEY `idx_subscription_plans_scope` (`company_id`,`event_category_id`,`event_type_id`,`religion_id`),
  KEY `idx_subscription_plans_cycle` (`company_id`,`billing_cycle`,`is_active`),
  KEY `fk_sub_plans_category` (`event_category_id`),
  KEY `fk_sub_plans_type` (`event_type_id`),
  KEY `fk_sub_plans_religion` (`religion_id`),
  KEY `fk_sub_plans_plan_type` (`plan_type_id`),
  KEY `idx_subscription_plans_badge` (`company_id`,`plan_badge_id`),
  KEY `fk_subscription_plans_badge` (`plan_badge_id`),
  CONSTRAINT `fk_sub_plans_category` FOREIGN KEY (`event_category_id`) REFERENCES `event_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_plans_plan_type` FOREIGN KEY (`plan_type_id`) REFERENCES `plan_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_plans_religion` FOREIGN KEY (`religion_id`) REFERENCES `religions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_plans_type` FOREIGN KEY (`event_type_id`) REFERENCES `event_types` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_subscription_plans_badge` FOREIGN KEY (`plan_badge_id`) REFERENCES `plan_badges` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `template_categories`
CREATE TABLE IF NOT EXISTS `template_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique per company; enforced in the service, not by an index, because rows are soft-deleted',
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint NOT NULL DEFAULT '1',
  `company_id` int DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_template_categories_company` (`company_id`,`deleted_at`),
  KEY `idx_template_categories_slug` (`company_id`,`slug`,`deleted_at`),
  KEY `idx_template_categories_listing` (`company_id`,`sort_order`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `translation_keys`
CREATE TABLE IF NOT EXISTS `translation_keys` (
  `id` int NOT NULL AUTO_INCREMENT,
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_id` int DEFAULT NULL,
  `default_value` text COLLATE utf8mb4_unicode_ci,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `group` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'common',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `key` (`key`),
  KEY `idx_translation_keys_group` (`group`)
) ENGINE=InnoDB AUTO_INCREMENT=990 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `translations`
CREATE TABLE IF NOT EXISTS `translations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int DEFAULT NULL,
  `translation_key_id` int NOT NULL,
  `language_id` int NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci,
  `status` enum('auto','reviewed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'auto',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '0=inactive,1=active,2=pending',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_translation_key_lang` (`translation_key_id`,`language_id`),
  KEY `fk_translations_lang` (`language_id`),
  CONSTRAINT `fk_translations_key` FOREIGN KEY (`translation_key_id`) REFERENCES `translation_keys` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_translations_lang` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=710 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `users`
CREATE TABLE IF NOT EXISTS `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `avatar` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `department_id` int DEFAULT NULL,
  `username` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `gender` enum('male','female','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marital_status` enum('married','unmarried') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country_id` int DEFAULT NULL,
  `state_id` int DEFAULT NULL,
  `city_id` int DEFAULT NULL,
  `pincode_id` int DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `department` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designation` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `doj` date DEFAULT NULL,
  `dor` date DEFAULT NULL,
  `timezone` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `login_access` tinyint NOT NULL DEFAULT '1',
  `email_verified_at` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `password_changed_at` datetime DEFAULT NULL,
  `password_reset_token` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `password_reset_expires` datetime DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '0' COMMENT '0=inactive,1=active,2=pending',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_email` (`email`),
  KEY `idx_users_role` (`role_id`),
  KEY `idx_users_company` (`company_id`),
  CONSTRAINT `fk_users_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_clients`
CREATE TABLE IF NOT EXISTS `vendor_clients` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `client_id` varchar(50) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `mobile` varchar(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `profile_pic` longtext,
  `registration_type` enum('guest','client') DEFAULT 'client',
  `plan` varchar(200) DEFAULT NULL,
  `subscription_id` int DEFAULT NULL,
  `is_active` tinyint DEFAULT '1',
  `address` text,
  `country` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `locality` varchar(100) DEFAULT NULL,
  `pincode` varchar(20) DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `login_access` tinyint(1) DEFAULT '0',
  `send_credentials_to_email` tinyint(1) DEFAULT '0',
  `client_type` enum('subscribed','unsubscribed') NOT NULL DEFAULT 'subscribed',
  `password` varchar(255) DEFAULT NULL,
  `password_changed_at` datetime DEFAULT NULL,
  `reset_token` varchar(6) DEFAULT NULL,
  `reset_token_expires_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vendor_clients_email_unique` (`email`),
  KEY `idx_vendor_id` (`vendor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `vendor_departments`
CREATE TABLE IF NOT EXISTS `vendor_departments` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `vendor_id` int unsigned NOT NULL,
  `company_id` int DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_vendor_departments_vendor_id` (`vendor_id`),
  KEY `idx_vendor_id` (`vendor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_email_categories`
CREATE TABLE IF NOT EXISTS `vendor_email_categories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_vec_vendor` (`vendor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_email_templates`
CREATE TABLE IF NOT EXISTS `vendor_email_templates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_vet_vendor` (`vendor_id`),
  KEY `idx_vet_category` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_newsletter_sends`
CREATE TABLE IF NOT EXISTS `vendor_newsletter_sends` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `company_id` int DEFAULT NULL,
  `template_id` int DEFAULT NULL,
  `template_name` varchar(255) NOT NULL,
  `category_id` int DEFAULT NULL,
  `user_type` enum('Guest','Registered') NOT NULL DEFAULT 'Registered',
  `plans` json DEFAULT NULL,
  `total_sent` int NOT NULL DEFAULT '0',
  `created_by` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_vendor_id` (`vendor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Table structure for `vendor_newsletter_sent_logs`
CREATE TABLE IF NOT EXISTS `vendor_newsletter_sent_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vendor_id` int unsigned NOT NULL,
  `campaign_id` bigint NOT NULL,
  `client_id` int NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `membership` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `template` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','sent','failed','bounced') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `opened_at` datetime DEFAULT NULL,
  `clicked_at` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_vendor_campaign` (`vendor_id`,`campaign_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `vendor_newsletter_sent_logs_ibfk_1` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_newsletters`
CREATE TABLE IF NOT EXISTS `vendor_newsletters` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vendor_id` int unsigned NOT NULL,
  `company_id` int unsigned DEFAULT NULL,
  `client_id` int NOT NULL,
  `client_type` enum('subscribed','unsubscribed') COLLATE utf8mb4_unicode_ci DEFAULT 'subscribed',
  `registration_type` enum('guest','client') COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_vendor_client` (`vendor_id`,`client_id`),
  KEY `idx_vendor` (`vendor_id`),
  KEY `idx_client` (`client_id`),
  CONSTRAINT `vendor_newsletters_ibfk_1` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vendor_newsletters_ibfk_2` FOREIGN KEY (`client_id`) REFERENCES `vendor_clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `vendor_staff`
CREATE TABLE IF NOT EXISTS `vendor_staff` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vendor_id` int NOT NULL,
  `role_id` int DEFAULT NULL,
  `department_id` int DEFAULT NULL,
  `emp_id` varchar(50) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `email` varchar(255) NOT NULL,
  `mobile` varchar(20) NOT NULL,
  `designation` varchar(200) DEFAULT NULL,
  `doj` date DEFAULT NULL,
  `dor` date DEFAULT NULL,
  `dob` date DEFAULT NULL,
  `profile_pic` longtext,
  `login_access` tinyint(1) DEFAULT '1',
  `password` varchar(255) DEFAULT NULL,
  `password_reset_token` varchar(10) DEFAULT NULL,
  `password_reset_expires` datetime DEFAULT NULL,
  `is_active` tinyint DEFAULT '1',
  `work_status` enum('active','inactive','resigned','relieved') DEFAULT 'active',
